 * In-flight request deduplication.
 *
 * Wraps an async function of one string key so that concurrent calls with
 * the same key share a single underlying promise. The shared entry is
 * cleared as soon as it settles, so a later call always refetches.
 * Rejections propagate to every waiter but are never cached.
 */
export function dedupe<K extends string, V>(
  fn: (key: K) => Promise<V>,
): (key: K) => Promise<V> {
  const inflight = new Map<K, Promise<V>>();

  return (key: K): Promise<V> => {
    const existing = inflight.get(key);
    if (existing) return existing;

    const promise = fn(key).finally(() => {
      // Clear only if this promise is still the registered one,
      // so a newer call for the same key is never clobbered.
      if (inflight.get(key) === promise) inflight.delete(key);
    });

    inflight.set(key, promise);
    return promise;
  };
}

/* ------------------------------------------------------------------ */
/* Read-through user layer built on top of dedupe()                    */
/* ------------------------------------------------------------------ */

export interface User {
  id: string;
  name: string;
}

/** Replaceable network stub backing getUser(). */
let fetchUserImpl: (id: string) => Promise<User> = async (id) => ({
  id,
  name: `user-${id}`,
});

export function setFetchStub(impl: (id: string) => Promise<User>): void {
  fetchUserImpl = impl;
}

const dedupedFetchUser = dedupe((id: string) => fetchUserImpl(id));

/** Concurrent calls for the same id share one in-flight fetch. */
export function getUser(id: string): Promise<User> {
  return dedupedFetchUser(id);
}
