import { dedupe, getUser, setFetchStub, type User } from '../src/index';

beforeEach(() => {
  setFetchStub(async (id) => ({ id, name: `user-${id}` }));
});

describe('dedupe', () => {
  it('coalesces two concurrent same-key calls into one fn invocation with identical results', async () => {
    const fn = vi.fn(async (key: string) => ({ key, value: Math.random() }));
    const wrapped = dedupe(fn);

    const [a, b] = await Promise.all([wrapped('x'), wrapped('x')]);

    expect(fn).toHaveBeenCalledTimes(1);
    expect(a).toBe(b); // same object identity
  });

  it('propagates rejection to all waiters and is not cached; a retry calls fn again', async () => {
    let fail = true;
    const fn = vi.fn(async (key: string) => {
      if (fail) throw new Error(`boom:${key}`);
      return { key };
    });
    const wrapped = dedupe(fn);

    const p1 = wrapped('k');
    const p2 = wrapped('k');

    await expect(p1).rejects.toThrow('boom:k');
    await expect(p2).rejects.toThrow('boom:k');
    expect(fn).toHaveBeenCalledTimes(1);

    fail = false;
    const result = await wrapped('k');
    expect(fn).toHaveBeenCalledTimes(2); // refetched after the failure
    expect(result).toEqual({ key: 'k' });
  });

  it('interleaved different keys are counted and resolved separately', async () => {
    const fn = vi.fn(async (key: string) => ({ key }));
    const wrapped = dedupe(fn);

    const a1 = wrapped('a');
    const b1 = wrapped('b');
    // 'a' settles while 'b' is still in flight, then 'a' is called again
    await a1;
    const a2 = wrapped('a');
    await Promise.all([b1, a2]);

    expect(fn).toHaveBeenCalledTimes(3);
    expect(fn.mock.calls.map((c) => c[0]).sort()).toEqual(['a', 'a', 'b']);

    const b2 = wrapped('b');
    await b2;
    expect(fn).toHaveBeenCalledTimes(4);
  });

  it('stress: 100 mixed calls over distinct keys invoke fn exactly once per key', async () => {
    const deferreds = new Map<string, { resolve: (u: User) => void }>();
    const fn = vi.fn(
      (key: string) =>
        new Promise<User>((resolve) => {
          deferreds.set(key, { resolve });
        }),
    );
    setFetchStub(fn as unknown as (id: string) => Promise<User>);

    const distinctKeys = Array.from({ length: 10 }, (_, i) => `user-${i}`);
    const promises: Promise<User>[] = [];
    for (let i = 0; i < 100; i++) {
      promises.push(getUser(distinctKeys[i % distinctKeys.length]));
    }

    // Nothing has settled yet: exactly one in-flight call per distinct key.
    expect(fn).toHaveBeenCalledTimes(distinctKeys.length);

    for (let round = 0; round < 10; round++) {
      for (const key of distinctKeys) {
        deferreds.get(key)!.resolve({ id: key, name: `name-${key}` });
        // Fire another wave while previous ones may still be pending.
        if (round < 9) promises.push(getUser(key));
      }
      await Promise.resolve();
    }

    const users = await Promise.all(promises);
    expect(users).toHaveLength(100);
    expect(users.every((u) => u.id === u.name.slice(5))).toBe(true);

    // Even after settling, later waves during the same tick never duplicate.
    expect(fn).toHaveBeenCalledTimes(distinctKeys.length);
  });
});
"})
